extends Node
## Runs one scripted scenario configuration to completion and dumps metrics
## JSON into results/. The wave budget is IDENTICAL across A–E so columns are
## comparable; only the active layers differ.

const Metrics := preload("res://combat/src/metrics/combat_metrics.gd")

## VS5-T4: every scenario uses one recorded seed; the value rides in each JSON dump.
const SEED := 20260825

const SCENARIOS := {
	"A": {"layers": ["PILOT"], "title": "pilot only"},
	"B": {"layers": ["MG"], "title": "MG only"},
	"C": {"layers": ["MG", "CC"], "title": "MG+CC"},
	"D": {"layers": ["PILOT", "MG"], "title": "pilot+MG"},
	"E": {"layers": ["PILOT", "MG", "CC"], "title": "full triangle"},
	"C240": {"layers": ["MG", "CC"], "title": "MG+CC mg_ammo 240",
		"overrides": {"mg_ammo": 240}},
	"A_S2": {"layers": ["PILOT"], "title": "pilot only x2 density",
		"overrides": {"_density": 2}},
	"A_E4": {"layers": ["PILOT"], "title": "pilot only aim err 4deg",
		"overrides": {"_aim_error": 4.0}},
}

const TIME_LIMIT := 220.0

var scenario_id := "A"
var _spawns: Array = []
var _spawned_all := false
var _done := false
var _density := 1
var _prev_core_hp := 0.0
var _prev_leaks := 0
var _ferry_sample := false


func _ready() -> void:
	var main = get_parent()
	var cfg = SCENARIOS.get(scenario_id, SCENARIOS["E"])
	seed(SEED)
	Metrics.reset_all()
	Metrics.inst().reset("%s (%s)" % [scenario_id, cfg.title])
	_apply_overrides(cfg.get("overrides", {}))
	Engine.time_scale = 4.0
	_build_layers(main, cfg.layers)
	core_done(main)
	print("[scenario %s] layers=%s" % [scenario_id, cfg.layers])


func _apply_overrides(ov: Dictionary) -> void:
	for k in ov:
		if k == "_density":
			_density = int(ov[k])
		else:
			var Stats = load("res://combat/data/combat_stats.gd")
			Stats.ensure().set(k, ov[k])


var _aim_error := 0.0


func _build_layers(main, layers: Array) -> void:
	if "MG" in layers:
		main.populate_socket("mg_west")
	if "CC" in layers:
		main.populate_socket("cc_center")
	if "PILOT" in layers:
		main.spawn_pilot(true)
		var ap = main.pilot.autopilot
		if ap != null:
			ap.aim_error_deg = float(_aim_error)
	main.refresh_pilot_refs()
	_spawns = _wave()


func core_done(main) -> void:
	main.core.died.connect(func(): _on_core_died())


func _on_core_died() -> void:
	if not _done:
		_finish("core_lost")


func _physics_process(dt: float) -> void:
	if _done:
		return
	var main = get_parent()
	var alive := 0
	for e in get_tree().get_nodes_in_group("enemies"):
		alive += 1
	Metrics.inst().tick(dt, alive)
	var t: float = Metrics.inst().elapsed
	var m = Metrics.inst()
	var ap = main.pilot.autopilot if main.pilot != null else null
	_ferry_sample = ap != null and ap.ferrying
	if _ferry_sample:
		m.ferry_seconds += dt
	var core_now: float = main.core.hp
	if _ferry_sample:
		m.core_damage_during_ferry += maxf(_prev_core_hp - core_now, 0.0)
		m.leaks_during_ferry += m.leaks - _prev_leaks
	_prev_core_hp = core_now
	_prev_leaks = m.leaks
	while not _spawns.is_empty() and _spawns[0][0] <= t:
		var s = _spawns.pop_front()
		main.spawn_enemy(s[1], main.ARENA.lanes[s[2]])
	if _spawns.is_empty() and alive == 0 and t > 1.0:
		_finish("cleared")
	elif t >= TIME_LIMIT:
		_finish("timeout")


func _wave() -> Array:
	var out := []
	var lane_cycle := [0, 1, 2, 1]
	for i in range(18 * _density):
		out.append([i * 2.6, 0, lane_cycle[i % 4]])
	out.append([10.0, 1, 0])
	out.append([24.0, 1, 2])
	out.append([14.0, 2, 1])
	out.append([30.0, 2, 1])
	out.sort_custom(func(a, b): return a[0] < b[0])
	return out


func _finish(outcome: String) -> void:
	_done = true
	Engine.time_scale = 1.0
	var m = Metrics.inst()
	m.outcome = outcome
	for e in get_tree().get_nodes_in_group("enemies"):
		e.queue_free()
	var main = get_parent()
	var mg_left := 0
	var cc_left := 0
	for s in main.sockets.values():
		if s.turret != null and is_instance_valid(s.turret):
			if s.turret.kind == "mg":
				mg_left += s.turret.ammo
			else:
				cc_left += s.turret.ammo
	m.ammo_remaining = {"mg": mg_left, "cc": cc_left}
	DirAccess.make_dir_recursive_absolute("res://results")
	m.dump("res://results/scenario_%s.json" % scenario_id)
	await get_tree().create_timer(0.3).timeout
	get_tree().quit(0 if outcome == "cleared" else 1)
